uint8_t door_guard_bin_cam(float x)
{
    if (x < 0.1f) return DOOR_GUARD_CAM_NONE;
    if (x < 0.34f) return DOOR_GUARD_CAM_PERSON_LO;
    if (x < 0.67f) return DOOR_GUARD_CAM_PERSON_MID;
    return DOOR_GUARD_CAM_PERSON_HI;
}

