static inline int score_visitor_points(const door_guard_inputs_t *in, const door_guard_think_t *th)
{
    (void)in; (void)th;
    return SCORE_VISITOR_POINTS_CAM[in->cam] + SCORE_VISITOR_POINTS_AUDIO[in->audio] + SCORE_VISITOR_POINTS_HEAT[in->heat];
}

