static const int16_t SCORE_SUSPICION_AUDIO[] = { 0, 0, 0, 1 };   /* none, voice, knock, loud */
static const int16_t SCORE_SUSPICION_LAST[] = { 0, 0, 2 };   /* none, ok, alert */
static const int16_t SCORE_SUSPICION_EXPECT[] = { 0, -2, -2, -2 };   /* none, owner, milkman, courier */
static inline int score_suspicion(const door_guard_inputs_t *in, const door_guard_think_t *th)
{
    (void)in; (void)th;
    return SCORE_SUSPICION_TOD[in->tod] + SCORE_SUSPICION_OWNER[in->owner] + SCORE_SUSPICION_AUDIO[in->audio] + SCORE_SUSPICION_LAST[in->last] + SCORE_SUSPICION_EXPECT[in->expect];
}

