{
    (void)in; (void)th;
    uint32_t f = 0;
    if (fact_wifi_up(in, th)) f |= 1u << DOOR_GUARD_FACT_WIFI_UP;
    if (fact_night(in, th)) f |= 1u << DOOR_GUARD_FACT_NIGHT;
    if (fact_high_threat(in, th)) f |= 1u << DOOR_GUARD_FACT_HIGH_THREAT;
    return f;
}

void door_guard_think(const door_guard_inputs_t *in, door_guard_think_t *th)
{
    door_guard_think_t zero = {0};
    *th = zero;
    /* visitor: first matching rule wins */
    if (score_visitor_points(in, th) >= 4)   /* visitor_points >= 4 */
        th->visitor = DOOR_GUARD_VISITOR_HI;
    else if (score_visitor_points(in, th) >= 2)   /* visitor_points >= 2 */
        th->visitor = DOOR_GUARD_VISITOR_MID;
    else th->visitor = DOOR_GUARD_VISITOR_LO;
    /* threat: first matching rule wins */
    if (th->visitor == DOOR_GUARD_VISITOR_LO)   /* visitor == lo */
        th->threat = DOOR_GUARD_THREAT_LO;
    else if ((th->visitor == DOOR_GUARD_VISITOR_HI) && (score_suspicion(in, th) >= 3))   /* visitor == hi and suspicion >= 3 */
        th->threat = DOOR_GUARD_THREAT_HI;
    else if ((th->visitor == DOOR_GUARD_VISITOR_HI) && (score_suspicion(in, th) >= 1))   /* visitor == hi and suspicion >= 1 */
        th->threat = DOOR_GUARD_THREAT_MID;
    else if ((th->visitor == DOOR_GUARD_VISITOR_MID) && (score_suspicion(in, th) >= 4))   /* visitor == mid and suspicion >= 4 */
        th->threat = DOOR_GUARD_THREAT_HI;
    else if ((th->visitor == DOOR_GUARD_VISITOR_MID) && (score_suspicion(in, th) >= 2))   /* visitor == mid and suspicion >= 2 */
        th->threat = DOOR_GUARD_THREAT_MID;
    else th->threat = DOOR_GUARD_THREAT_LO;
}

uint32_t door_guard_want(const door_guard_inputs_t *in, const door_guard_think_t *th)
{
    (void)in; (void)th;
    uint32_t w = 0;
    /* logged: true */
    w |= DOOR_GUARD_OUT(LOGGED);
    /* evidence: visitor != lo */
    if (th->visitor != DOOR_GUARD_VISITOR_LO) w |= DOOR_GUARD_OUT(EVIDENCE);
    /* informed_low: threat == mid or (threat == lo and visitor != lo and expect == none and recent != many) */
    if ((th->threat == DOOR_GUARD_THREAT_MID) || ((th->threat == DOOR_GUARD_THREAT_LO) && (th->visitor != DOOR_GUARD_VISITOR_LO) && (in->expect == DOOR_GUARD_EXPECT_NONE) && (in->recent != DOOR_GUARD_RECENT_MANY))) w |= DOOR_GUARD_OUT(INFORMED_LOW);
    /* informed_high: threat == hi */
    if (th->threat == DOOR_GUARD_THREAT_HI) w |= DOOR_GUARD_OUT(INFORMED_HIGH);
    /* deterred: threat == hi or (threat == mid and night) */
    if ((th->threat == DOOR_GUARD_THREAT_HI) || ((th->threat == DOOR_GUARD_THREAT_MID) && fact_night(in, th))) w |= DOOR_GUARD_OUT(DETERRED);
    /* secured: threat == hi */
    if (th->threat == DOOR_GUARD_THREAT_HI) w |= DOOR_GUARD_OUT(SECURED);
    /* help: threat == hi and owner == away and last == alert */
    if ((th->threat == DOOR_GUARD_THREAT_HI) && (in->owner == DOOR_GUARD_OWNER_AWAY) && (in->last == DOOR_GUARD_LAST_ALERT)) w |= DOOR_GUARD_OUT(HELP);
    return w;
}

bool door_guard_situation(uint32_t index, door_guard_inputs_t *in)
{
    if (index >= DOOR_GUARD_N_SITUATIONS) return false;
    in->last = (uint8_t)(index % DOOR_GUARD_LAST_COUNT); index /= DOOR_GUARD_LAST_COUNT;
    in->recent = (uint8_t)(index % DOOR_GUARD_RECENT_COUNT); index /= DOOR_GUARD_RECENT_COUNT;
    in->expect = (uint8_t)(index % DOOR_GUARD_EXPECT_COUNT); index /= DOOR_GUARD_EXPECT_COUNT;
    in->wifi = (uint8_t)(index % DOOR_GUARD_WIFI_COUNT); index /= DOOR_GUARD_WIFI_COUNT;
    in->owner = (uint8_t)(index % DOOR_GUARD_OWNER_COUNT); index /= DOOR_GUARD_OWNER_COUNT;
    in->tod = (uint8_t)(index % DOOR_GUARD_TOD_COUNT); index /= DOOR_GUARD_TOD_COUNT;
    in->heat = (uint8_t)(index % DOOR_GUARD_HEAT_COUNT); index /= DOOR_GUARD_HEAT_COUNT;
    in->audio = (uint8_t)(index % DOOR_GUARD_AUDIO_COUNT); index /= DOOR_GUARD_AUDIO_COUNT;
    in->cam = (uint8_t)(index % DOOR_GUARD_CAM_COUNT); index /= DOOR_GUARD_CAM_COUNT;
    return true;
}

int door_guard_decode(const uint8_t *out, int n, door_guard_think_t *th, uint8_t *plan, int max_plan)
{
    int i = 0;
    if (i >= n || out[i] < DOOR_GUARD_TOK_VISITOR_LO || out[i] >= DOOR_GUARD_TOK_VISITOR_LO + DOOR_GUARD_VISITOR_COUNT) return -1;
    if (th) th->visitor = (uint8_t)(out[i] - DOOR_GUARD_TOK_VISITOR_LO);
    i++;
    if (i >= n || out[i] < DOOR_GUARD_TOK_THREAT_LO || out[i] >= DOOR_GUARD_TOK_THREAT_LO + DOOR_GUARD_THREAT_COUNT) return -1;
    if (th) th->threat = (uint8_t)(out[i] - DOOR_GUARD_TOK_THREAT_LO);
    i++;
    if (i >= n || out[i++] != DOOR_GUARD_TOK_PLAN) return -1;
    int len = 0;
    for (; i < n && out[i] != DOOR_GUARD_TOK_EOS; i++) {
        if (out[i] < DOOR_GUARD_TOK_LOG || out[i] > DOOR_GUARD_TOK_CALL_HELP || len >= max_plan) return -1;
        plan[len++] = (uint8_t)(out[i] - DOOR_GUARD_TOK_LOG);
    }
    if (i >= n) return -1;   /* no <eos> */
    return len;
}
